import { NextRequest, NextResponse } from "next/server";

/**
 * These routes do not require authentication.
 */
export const PUBLIC_PATHS = ["/", "/auth", "/api/login", "/api/logout"];

/**
 * These are the login and logout paths used by Next.js Firebase Auth Edge.
 */
export const AUTH_API_PATHS = {
  login: "/api/login",
  logout: "/api/logout",
};

/**
 * The default path to redirect unauthenticated users to.
 */
export const LOGIN_PATH = "/auth";

/**
 * The default path to redirect authenticated users to after login.
 */
export const DEFAULT_LOGIN_REDIRECT = "/dashboard";

export function redirectToLogin(request: NextRequest) {
  if (PUBLIC_PATHS.includes(request.nextUrl.pathname)) {
    return NextResponse.next();
  }

  const url = request.nextUrl.clone();
  url.pathname = LOGIN_PATH;
  url.searchParams.set("redirect", request.nextUrl.pathname);
  return NextResponse.redirect(url);
}

function required(name: string, value: string | undefined) {
  if (!value) {
    throw new Error(`Missing ${name}.`);
  }
  return value;
}

export const authConfig = {
  apiKey: required(
    "NEXT_PUBLIC_FIREBASE_API_KEY",
    process.env.NEXT_PUBLIC_FIREBASE_API_KEY,
  ),
  cookieName: "ff-session",
  cookieSignatureKeys: [
    required("COOKIE_SECRET_KEY", process.env.COOKIE_SECRET_KEY),
  ],
  cookieSerializeOptions: {
    path: "/",
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    sameSite: "lax" as const,
    maxAge: 12 * 60 * 60 * 24, // 12 days
  },
  serviceAccount: {
    projectId: required(
      "NEXT_PUBLIC_FIREBASE_PROJECT_ID or FIREBASE_PROJECT_ID",
      process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID ??
        process.env.FIREBASE_PROJECT_ID,
    ),
    clientEmail: required(
      "FIREBASE_CLIENT_EMAIL",
      process.env.FIREBASE_CLIENT_EMAIL,
    ),
    privateKey: process.env.FIREBASE_PRIVATE_KEY
      ? process.env.FIREBASE_PRIVATE_KEY.replace(/\\n/g, "\n")
      : "",
  },
};

import { getApp, getApps, initializeApp } from "firebase/app";
import { getAuth } from "firebase/auth";

const firebaseConfig = {
  apiKey: process.env.NEXT_PUBLIC_FIREBASE_API_KEY,
  authDomain: process.env.NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN,
  projectId: process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID,
  appId: process.env.NEXT_PUBLIC_FIREBASE_APP_ID,
  storageBucket: process.env.NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.NEXT_PUBLIC_FIREBASE_MESSAGING_SENDER_ID,
};

export function getFirebaseAuth() {
  const app = getApps().length ? getApp() : initializeApp(firebaseConfig);
  return getAuth(app);
}

import type { AuthError } from "firebase/auth";

const messages: Record<string, string> = {
  "auth/popup-closed-by-user":
    "The sign-in window was closed before finishing.",
  "auth/cancelled-popup-request": "Sign-in was cancelled.",
  "auth/popup-blocked":
    "The sign-in popup was blocked. Allow popups and try again.",
  "auth/account-exists-with-different-credential":
    "That email is already used with a different sign-in method.",
  "auth/network-request-failed":
    "Network error. Check your connection and try again.",
};

export function mapFirebaseError(error: AuthError) {
  return messages[error.code] ?? "Sign-in failed. Try again.";
}

"use client";

import { useEffect } from "react";
import { onIdTokenChanged } from "firebase/auth";
import { getFirebaseAuth } from "@/lib/firebase/client-app";

export function AuthProvider({ children }: { children: React.ReactNode }) {
  useEffect(() => {
    const auth = getFirebaseAuth();

    return onIdTokenChanged(auth, async (user) => {
      if (user) {
        const token = await user.getIdToken();

        await fetch("/api/login", {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });
      } else {
        await fetch("/api/logout");
      }
    });
  }, []);

  return <>{children}</>;
}

import { authConfig } from "@/lib/firebase/auth-config";
import { getFirebaseAuth } from "next-firebase-auth-edge/lib/auth";
import { NextRequest, NextResponse } from "next/server";

export async function GET(request: NextRequest) {
  const auth = request.headers.get("Authorization");
  const token = auth?.split("Bearer ")[1];

  if (!token) {
    return NextResponse.json({ error: "Missing token" }, { status: 401 });
  }

  const { getCustomIdAndRefreshTokens } = getFirebaseAuth(
    authConfig.serviceAccount,
    authConfig.apiKey,
  );

  try {
    const { idToken, refreshToken } = await getCustomIdAndRefreshTokens(token);

    const response = new NextResponse(JSON.stringify({ status: "success" }), {
      status: 200,
      headers: { "Content-Type": "application/json" },
    });

    response.cookies.set(authConfig.cookieName, idToken, {
      ...authConfig.cookieSerializeOptions,
    });

    if (refreshToken) {
      response.cookies.set(`${authConfig.cookieName}-refresh`, refreshToken, {
        ...authConfig.cookieSerializeOptions,
      });
    }

    return response;
  } catch (e) {
    console.error("Login failed: ", e);
    return NextResponse.json({ error: "Invalid token" }, { status: 401 });
  }
}

import { authConfig } from "@/lib/firebase/auth-config";
import { NextResponse } from "next/server";

export async function GET() {
  const response = new NextResponse(JSON.stringify({ status: "success" }), {
    status: 200,
    headers: { "Content-Type": "application/json" },
  });

  response.cookies.set(authConfig.cookieName, "", {
    ...authConfig.cookieSerializeOptions,
    maxAge: 0,
  });

  response.cookies.set(`${authConfig.cookieName}-refresh`, "", {
    ...authConfig.cookieSerializeOptions,
    maxAge: 0,
  });

  return response;
}

import { NextRequest, NextResponse } from "next/server";
import { authMiddleware } from "next-firebase-auth-edge";
import { authConfig } from "./lib/firebase/auth-config";
import {
  PUBLIC_PATHS,
  AUTH_API_PATHS,
  LOGIN_PATH,
  DEFAULT_LOGIN_REDIRECT,
  redirectToLogin,
} from "./config/routes";

export async function proxy(request: NextRequest) {
  if (request.nextUrl.pathname === "/login") {
    return NextResponse.redirect(new URL("/auth", request.url));
  }

  return authMiddleware(request, {
    loginPath: AUTH_API_PATHS.login,
    logoutPath: AUTH_API_PATHS.logout,
    apiKey: authConfig.apiKey,
    cookieName: authConfig.cookieName,
    cookieSignatureKeys: authConfig.cookieSignatureKeys,
    cookieSerializeOptions: authConfig.cookieSerializeOptions,
    serviceAccount: authConfig.serviceAccount,
    handleValidToken: async ({ decodedToken }, headers) => {
      if (
        PUBLIC_PATHS.includes(request.nextUrl.pathname) &&
        request.nextUrl.pathname === LOGIN_PATH
      ) {
        return NextResponse.redirect(
          new URL(DEFAULT_LOGIN_REDIRECT, request.url),
        );
      }

      headers.set("x-signed-in", "1");
      if (decodedToken.email) {
        headers.set("x-user-email", decodedToken.email);
      }

      return NextResponse.next({
        request: {
          headers,
        },
      });
    },
    handleInvalidToken: async (reason) => {
      if (!PUBLIC_PATHS.includes(request.nextUrl.pathname)) {
        console.info("Missing or invalid credentials", { reason });
      }

      return redirectToLogin(request);
    },
    handleError: async (error) => {
      console.error("Unhandled authentication error", { error });

      return redirectToLogin(request);
    },
  });
}

export const config = {
  matcher: [
    "/",
    "/((?!_next|favicon.ico|api|.*\\.).*)",
    "/api/login",
    "/api/logout",
  ],
};

"use client";

import { useState } from "react";
import {
