import { upsertUser } from "@/lib/db/users";
import type { AuthProviderName } from "@/lib/db/schema";
import { authConfig } from "@/lib/firebase/auth-config";
import { getFirebaseAuth } from "next-firebase-auth-edge/auth";
import type { DecodedIdToken } from "next-firebase-auth-edge/auth";
import { setAuthCookies } from "next-firebase-auth-edge/next/cookies";
import { NextRequest, NextResponse } from "next/server";

function authProvider(token: DecodedIdToken): AuthProviderName | null {
  if (token.firebase.sign_in_provider === "google.com") return "google";
  if (token.firebase.sign_in_provider === "github.com") return "github";
  return null;
}

function accountId(token: DecodedIdToken) {
  const ids = token.firebase.identities[token.firebase.sign_in_provider];
  if (Array.isArray(ids) && typeof ids[0] === "string") return ids[0];
  return token.uid;
}

export async function GET(request: NextRequest) {
  const header = request.headers.get("Authorization");
  const token = header?.split("Bearer ")[1];

  if (!token) {
    return NextResponse.json({ error: "Missing token" }, { status: 401 });
  }

  const { verifyIdToken } = getFirebaseAuth(
    authConfig.serviceAccount,
    authConfig.apiKey,
  );

  try {
    const decoded = await verifyIdToken(token);
    const provider = authProvider(decoded);

    if (!provider) {
      return NextResponse.json(
        { error: "Unsupported sign-in provider" },
        { status: 401 },
      );
    }

    await upsertUser({
      email: decoded.email,
      name: decoded.name,
      image: decoded.picture,
      provider,
      accountId: accountId(decoded),
    });

    return setAuthCookies(request.headers, authConfig);
  } catch (e) {
    console.error("Login failed: ", e);
    return NextResponse.json({ error: "Invalid token" }, { status: 401 });
  }
}

